import { createClient } from '@supabase/supabase-js';
import { createAccountWorkspace } from './admin-accounts.js';
import { emptyPersonal, createPersonalDataController, renderClientDashboard, renderSharedPlan, localDay } from './client-data.js';

const APP_BUILD_ID = __APP_BUILD_ID__;
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const supabase = createClient(supabaseUrl, supabaseKey);
const inviteParams = new URLSearchParams(window.location.hash.replace(/^#/, ''));
const queryAuthType = new URLSearchParams(window.location.search).get('type');
let passwordSetupFlow = ['invite', 'recovery'].includes(inviteParams.get('type')) || ['invite', 'recovery'].includes(queryAuthType);
const emptyData=()=>({users:[],recipes:[],notifications:[],...emptyPersonal()});
let data=emptyData(), currentUser=null, page='home', activeFilter='All', recipeQuery='', modal=null, toastTimer, pushSubscribed=false;
const personalController=createPersonalDataController({supabase,getUser:()=>currentUser,getData:()=>data,notify:message=>toast(message),render:()=>render()});
let resumeCheckAt=0, resumeCheckPending=false;
let managedAccountId=null;
const accountWorkspace=createAccountWorkspace({supabase,notify:message=>toast(message),onClose:()=>{managedAccountId=null;accountWorkspace.close();render()},onChanged:()=>{refreshSharedData().then(loadAdminDirectory)}});

const app=document.getElementById('app');
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const initials=(s='B')=>s.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const roleName=r=>({client:'Client',coach:'Coach',admin:'Super admin'}[r]||'Client');
const isCoach=()=>currentUser?.role==='coach'||currentUser?.role==='admin';
async function loadAdminDirectory(){if(currentUser?.role!=='admin')return;const {data:directory,error}=await supabase.functions.invoke('admin-list-users',{body:{}});if(error){console.error('Could not load private admin account directory:',error);return}if(!Array.isArray(directory?.users))return;const currentById=new Map(data.users.map(u=>[u.id,u]));data.users=directory.users.map(u=>({id:u.id,name:currentById.get(u.id)?.name||u.name,email:u.email||'',role:u.role==='super_admin'?'admin':u.role}))}
const todayLabel=()=>new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function navForRole(){if(currentUser.role==='coach')return [['home','⌂','Overview'],['clients','♙','Clients'],['recipes','♧','Recipes'],['broadcasts','◉','Broadcasts'],['profile','◯','Profile']];if(currentUser.role==='admin')return [['home','⌂','Overview'],['accounts','♙','Accounts'],['recipes','♧','Recipes'],['broadcasts','◉','Broadcasts'],['profile','◯','Profile']];return [['home','⌂','Home'],['plan','▤','My plan'],['recipes','♧','Recipes'],['notifications','◉','Inbox'],['profile','◯','Profile']]}
function titleFor(p){return ({home:'Overview',plan:'My plan',recipes:'Recipe library',notifications:'Notifications',clients:'Clients',accounts:'Accounts',broadcasts:'Broadcasts',profile:'My profile'})[p]||'Overview'}
function renderLogin(){app.innerHTML=`<main class="auth-screen"><section class="auth-visual"><div class="auth-brand"><img class="brand-mark brand-logo" src="/assets/icon-192.png" alt="BodyfyStudio logo"><span>BODYFYSTUDIO</span></div><img class="auth-logo" src="BodyfyStudio%20Logo.jpg" alt="BodyfyStudio — Lose weight, build confidence"><div class="auth-tagline"><div class="eyebrow">Your wellness, your pace</div><h2>A healthier you<br>starts with one step.</h2><p>Personalized support for your weight-loss journey, with simple tools to help healthy habits stick.</p></div><div class="auth-foot">© 2026 BodyfyStudio · Private client portal</div></section><section class="auth-panel"><div class="auth-box"><div class="auth-copy"><div class="eyebrow">Welcome to BodyfyStudio</div><h1 id="auth-title">Sign in to your journey</h1><p id="auth-description">Sign in to access your BodyfyStudio account, recipes, and coach updates.</p></div><div id="auth-form">${loginForm()}</div></div></section></main>`;bindLogin();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{})}
function loginForm(){return `<form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" type="email" placeholder="you@example.com" required autocomplete="email"></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" placeholder="Enter your password" required autocomplete="current-password"></div><button class="btn btn-primary btn-block" type="submit">Sign in <span>→</span></button></form><div class="auth-switch"><button data-action="forgot-password">Forgot your password?</button></div><div class="auth-switch">New to BodyfyStudio? <button data-action="show-signup">Create a client account</button></div>`}
function renderPasswordSetup(){app.innerHTML=`<main class="auth-screen"><section class="auth-panel"><div class="auth-box"><div class="auth-copy"><div class="eyebrow">Finish setting up your account</div><h1>Create your password</h1><p>Choose a password to finish accepting your BodyfyStudio invitation.</p></div><form id="set-password-form"><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"></div><div class="field"><label for="confirm-password">Confirm password</label><input id="confirm-password" type="password" minlength="8" required autocomplete="new-password" placeholder="Enter it again"></div><button class="btn btn-primary btn-block" type="submit">Save password <span>→</span></button></form></div></section></main>`;document.getElementById('set-password-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),password=document.getElementById('new-password').value,confirm=document.getElementById('confirm-password').value;if(password!==confirm){toast('The passwords do not match.');return}button.disabled=true;const {error}=await supabase.auth.updateUser({password});button.disabled=false;if(error){toast(`Could not save password: ${error.message}`);return}passwordSetupFlow=false;history.replaceState({},document.title,window.location.pathname);const {data:{session}}=await supabase.auth.getSession();if(session){toast('Password saved. Your account is ready.');await acceptSession(session)}else{renderLogin();toast('Password saved. Please sign in.')}})}
function renderRecovery(){app.innerHTML=`<main class="auth-screen"><section class="auth-panel"><div class="auth-box"><div class="auth-copy"><div class="eyebrow">Account recovery</div><h1>Reset your password</h1><p>Enter your account email and we’ll send you a secure password reset link.</p></div><form id="recovery-form"><div class="field"><label for="recovery-email">Email address</label><input id="recovery-email" type="email" required autocomplete="email" placeholder="you@example.com"></div><button class="btn btn-primary btn-block" type="submit">Send reset link <span>→</span></button></form><div class="auth-switch"><button data-action="show-login">Back to sign in</button></div></div></section></main>`;document.getElementById('recovery-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const {error}=await supabase.auth.resetPasswordForEmail(document.getElementById('recovery-email').value.trim(),{redirectTo:window.location.origin});button.disabled=false;if(error){toast(`Could not send reset link: ${error.message}`);return}toast('Password reset email sent. Check your inbox.')})}
function signupForm(){return `<form id="signup-form"><div class="field"><label for="signup-name">Your name</label><input id="signup-name" required placeholder="Full name" autocomplete="name"></div><div class="field"><label for="signup-email">Email address</label><input id="signup-email" type="email" required placeholder="you@example.com" autocomplete="email"></div><div class="field"><label for="signup-password">Create a password</label><input id="signup-password" type="password" minlength="6" required placeholder="At least 6 characters" autocomplete="new-password"></div><button class="btn btn-primary btn-block" type="submit">Create client account <span>→</span></button></form><div class="auth-switch">Already have an account? <button data-action="show-login">Sign in</button></div><div class="role-notice">Client registration is open in this demo. Coach and super admin access is assigned separately in the real app.</div>`}
function bindLogin(){document.querySelector('[data-action="show-signup"]')?.addEventListener('click',()=>{document.getElementById('auth-title').textContent='Create your client account';document.getElementById('auth-description').textContent='Create your secure client login. New self-registered accounts start with client access.';document.getElementById('auth-form').innerHTML=signupForm();bindSignup()});document.querySelector('[data-action="show-login"]')?.addEventListener('click',renderLogin);document.querySelector('[data-action="forgot-password"]')?.addEventListener('click',renderRecovery);document.getElementById('login-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;const {data:result,error}=await supabase.auth.signInWithPassword({email:document.getElementById('login-email').value.trim(),password:document.getElementById('login-password').value});button.disabled=false;if(error){toast(error.message);return}await acceptSession(result.session)});}
function bindSignup(){document.getElementById('signup-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]');button.disabled=true;const {data:result,error}=await supabase.auth.signUp({email:document.getElementById('signup-email').value.trim(),password:document.getElementById('signup-password').value,options:{data:{display_name:document.getElementById('signup-name').value.trim()},emailRedirectTo:window.location.origin}});button.disabled=false;if(error){toast(error.message);return}if(result.session){await acceptSession(result.session);toast('Your client account is ready.')}else{toast('Account created. Check your email to confirm it, then sign in.')}});}
let acceptingSessionId=null;
async function acceptSession(session){if(currentUser?.id===session.user.id||acceptingSessionId===session.user.id)return;acceptingSessionId=session.user.id;const {data:profile,error:profileError}=await supabase.from('profiles').select('display_name').eq('id',session.user.id).single();if(profileError){acceptingSessionId=null;toast(`Signed in, but profile could not load: ${profileError.message}`);return}const {data:roleRow,error:roleError}=await supabase.from('user_roles').select('role').eq('user_id',session.user.id).single();if(roleError){acceptingSessionId=null;toast(`Account access could not load: ${roleError.message}`);return}personalController.reset();data=emptyData();currentUser={id:session.user.id,name:profile.display_name,email:session.user.email,role:roleRow.role==='super_admin'?'admin':roleRow.role};acceptingSessionId=null;page='home';await refreshSharedData();if(currentUser.role==='admin')await loadAdminDirectory();if(currentUser.role==='client')await refreshPushStatus();render();subscribeToInbox();}
async function signOut(){personalController.reset();managedAccountId=null;accountWorkspace.close();if(currentUser?.role==='client')await disablePushNotifications(true);await supabase.removeChannel(inboxChannel);inboxChannel=null;await supabase.auth.signOut();currentUser=null;modal=null;data=emptyData();renderLogin()}
let inboxChannel=null;
let sharedRefreshGeneration=0;
async function refreshSharedData(){
  const user=currentUser;if(!user)return;
  const request=++sharedRefreshGeneration;
  const recipesQuery=supabase.from('recipes').select('id,author_id,title,category,description,ingredients,steps,prep_minutes,calories_estimate,emoji,created_at').eq('published',true).order('created_at',{ascending:false});
  let noticesQuery=user.role==='client'?supabase.from('broadcast_recipients').select('broadcast_id,read_at,broadcasts(id,kind,title,message,action_url,created_at)').eq('client_id',user.id).order('created_at',{ascending:false}):supabase.from('broadcasts').select('id,kind,title,message,action_url,created_at').order('created_at',{ascending:false}).limit(100);
  if(user.role==='coach')noticesQuery=noticesQuery.eq('author_id',user.id);
  const [recipesResult,noticesResult]=await Promise.all([recipesQuery,noticesQuery]);
  if(currentUser?.id!==user.id||request!==sharedRefreshGeneration)return;
  if(recipesResult.error){toast('Recipes unavailable: '+recipesResult.error.message);data.recipes=[];}
  else data.recipes=recipesResult.data.map(r=>({id:r.id,title:r.title,category:r.category,time:r.prep_minutes,calories:r.calories_estimate||0,emoji:r.emoji,description:r.description,ingredients:r.ingredients,steps:r.steps,author:r.author_id===user.id?user.name:'BodyfyStudio coach',savedBy:[]}));
  if(noticesResult.error){toast('Inbox unavailable: '+noticesResult.error.message);data.notifications=[];}
  else if(user.role==='client')data.notifications=noticesResult.data.filter(x=>x.broadcasts).map(x=>({id:x.broadcast_id,kind:x.broadcasts.kind,title:x.broadcasts.title,message:x.broadcasts.message,link:x.broadcasts.action_url,created:Date.parse(x.broadcasts.created_at),read:Boolean(x.read_at)}));
  else data.notifications=noticesResult.data.map(x=>({id:x.id,kind:x.kind,title:x.title,message:x.message,link:x.action_url,created:Date.parse(x.created_at),read:true,author:user.name}));
  await personalController.load();
  if(currentUser?.id!==user.id||request!==sharedRefreshGeneration)return;
  if(user.role==='admin'){
    const [profiles,roles]=await Promise.all([supabase.from('profiles').select('id,display_name').order('created_at',{ascending:false}),supabase.from('user_roles').select('user_id,role')]);
    if(currentUser?.id!==user.id||request!==sharedRefreshGeneration)return;
    if(profiles.error||roles.error){toast('Account list unavailable.');data.users=[user];}
    else {const byId=new Map(roles.data.map(r=>[r.user_id,r.role]));data.users=profiles.data.map(p=>({id:p.id,name:p.display_name,email:p.id===user.id?user.email:'',role:byId.get(p.id)==='super_admin'?'admin':byId.get(p.id)||'client'}));}
  }else if(user.role==='coach'){
    const assignments=await supabase.from('coach_assignments').select('client_id').eq('coach_id',user.id);
    if(currentUser?.id!==user.id||request!==sharedRefreshGeneration)return;
    if(assignments.error){data.users=[user];toast('Assigned clients could not load.');}
    else if(assignments.data.length){const profiles=await supabase.from('profiles').select('id,display_name').in('id',assignments.data.map(a=>a.client_id));if(currentUser?.id!==user.id||request!==sharedRefreshGeneration)return;data.users=[user,...(profiles.data||[]).map(p=>({id:p.id,name:p.display_name,role:'client'}))];}
    else data.users=[user];
  }else data.users=[user];
}
let liveRefreshTimer;
function isEditing(){return modal||document.activeElement?.matches('input,textarea,select')||document.querySelector('.habit-form[open],.account-editor')}
function subscribeToInbox(){
  if(!currentUser)return;
  if(inboxChannel)supabase.removeChannel(inboxChannel);
  const user=currentUser;
  const changed=()=>{clearTimeout(liveRefreshTimer);liveRefreshTimer=setTimeout(async()=>{if(currentUser?.id!==user.id||personalController.busy())return;await refreshSharedData();if(currentUser?.id===user.id&&!isEditing())render()},200)};
  inboxChannel=supabase.channel(`account-${user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'recipe_favorites',filter:`user_id=eq.${user.id}`},changed);
  if(user.role==='client'){
    for(const table of ['daily_habits','plan_checklist','client_plans','coach_assignments','appointments'])inboxChannel=inboxChannel.on('postgres_changes',{event:'*',schema:'public',table,filter:`client_id=eq.${user.id}`},changed);
    inboxChannel=inboxChannel.on('postgres_changes',{event:'*',schema:'public',table:'broadcast_recipients',filter:`client_id=eq.${user.id}`},payload=>{changed();if(payload.eventType==='INSERT'&&page!=='notifications')toast('Your coach sent a new update.')});
  }
  inboxChannel.subscribe();
}
function vapidKeyBytes(value){const padded=value+'='.repeat((4-value.length%4)%4);const base64=padded.replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(base64),c=>c.charCodeAt(0))}
async function refreshPushStatus(){pushSubscribed=false;if(!('serviceWorker'in navigator)||!('PushManager'in window))return;try{const registration=await navigator.serviceWorker.ready;pushSubscribed=Boolean(await registration.pushManager.getSubscription())}catch{pushSubscribed=false}}
async function togglePushNotifications(){if(currentUser?.role!=='client')return;if(pushSubscribed){await disablePushNotifications(false);return}const publicKey=import.meta.env.VITE_VAPID_PUBLIC_KEY;if(!publicKey){toast('Push notifications are not configured yet.');return}if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){toast('This browser does not support push notifications.');return}const isIOS=/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);const isInstalled=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(isIOS&&!isInstalled){toast('On iPhone, add BodyfyStudio to your Home Screen first.');return}try{const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(permission!=='granted'){toast('Allow notifications for BodyfyStudio in your device settings.');return}const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidKeyBytes(publicKey)});const details=subscription.toJSON();if(!details.endpoint||!details.keys?.p256dh||!details.keys?.auth)throw new Error('The browser did not return a complete push subscription.');const {error}=await supabase.from('push_subscriptions').upsert({user_id:currentUser.id,endpoint:details.endpoint,p256dh:details.keys.p256dh,auth_key:details.keys.auth},{onConflict:'user_id,endpoint'});if(error){if(subscription)await subscription.unsubscribe();throw error}pushSubscribed=true;render();toast('Push notifications are enabled on this device.')}catch(error){console.error('Could not enable push notifications:',error);toast(`Could not enable notifications: ${error.message||'Please try again.'}`)}}
async function disablePushNotifications(quiet){try{if(!('serviceWorker'in navigator)||!('PushManager'in window)){pushSubscribed=false;return}const registration=await navigator.serviceWorker.ready;const subscription=await registration.pushManager.getSubscription();if(subscription&&currentUser){const {error}=await supabase.from('push_subscriptions').delete().eq('user_id',currentUser.id).eq('endpoint',subscription.endpoint);if(error)throw error;await subscription.unsubscribe()}pushSubscribed=false;if(!quiet){render();toast('Push notifications are disabled on this device.')}}catch(error){console.error('Could not disable push notifications:',error);if(!quiet)toast(`Could not disable notifications: ${error.message||'Please try again.'}`)}}
async function sendBroadcastPush(broadcastId){const {data:result,error}=await supabase.functions.invoke('send-broadcast-push',{body:{broadcastId}});if(error){let detail=error.message;try{const response=error.context?.clone?.();if(response){const body=await response.json();detail=body.error||body.message||detail}}catch{}console.error('Push delivery could not be started:',detail);return {error:detail}}return result}
function render(){if(!currentUser)return renderLogin();const nav=navForRole();if(currentUser.role==='client'&&!['home','plan','recipes','notifications','profile'].includes(page))page='home';if(currentUser.role==='coach'&&!['home','clients','recipes','broadcasts','profile'].includes(page))page='home';if(currentUser.role==='admin'&&!['home','accounts','recipes','broadcasts','profile'].includes(page))page='home';const currentTitle=titleFor(page);app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img class="brand-mark brand-logo" src="/assets/icon-192.png" alt="BodyfyStudio logo"><div><div class="brand-name">BODYFYSTUDIO</div><div class="brand-caption">WELLNESS, YOUR WAY</div></div></div><div class="nav-label">Workspace</div><nav class="nav-list">${nav.map(([key,icon,label])=>navLink(key,icon,label)).join('')}</nav><div class="sidebar-bottom"><div class="coach-card"><div class="coach-label">YOUR COACH</div><div class="coach-name">${currentUser.role==='client'?esc(data.personal?.coach?.name||'Not assigned yet'):currentUser.role==='admin'?'Studio team':'BodyfyStudio clients'}</div><p>${currentUser.role==='client'?'Your plan is designed around your routine. Small steps, steady progress.':currentUser.role==='admin'?'Manage roles, review content, and support the coaching team.':'A little encouragement can make a big difference.'}</p></div><div class="account-mini"><div class="avatar ${currentUser.role==='coach'?'orange':''}">${esc(initials(currentUser.name))}</div><div class="mini-meta"><div class="mini-name">${esc(currentUser.name)}</div><div class="mini-role">${roleName(currentUser.role)}</div></div><button class="signout" title="Sign out" data-action="signout">↪</button></div></div></aside><main class="main-area"><header class="topbar"><div class="breadcrumb">BodyfyStudio <span> / </span> <strong>${currentTitle}</strong></div><div class="top-actions"><div class="offline-pill"><i></i> Supabase connected</div>${currentUser.role==='client'?`<button class="icon-button" aria-label="Open notifications" data-nav="notifications">♧${data.notifications.length?'<span class="dot"></span>':''}</button>`:''}<div class="top-date">${todayLabel()}</div></div></header><section class="content">${data.personalError?`<div class="notice-bar" role="alert">${esc(data.personalError)} <button class="link-button" data-personal-action data-reload-personal>Retry</button></div>`:``}${renderPage()}</section><nav class="mobile-nav">${nav.map(([key,icon,label])=>`<button class="nav-item ${page===key?'active':''}" data-nav="${key}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}</nav></main>${modal?renderModal():''}</div>`;bindApp();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}
function navLink(key,icon,label){return `<button class="nav-item ${page===key?'active':''}" data-nav="${key}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`}
function renderPage(){if(page==='recipes')return renderRecipes();if(page==='plan')return renderPlan();if(page==='notifications')return renderNotifications();if(page==='clients')return renderClients();if(page==='accounts')return renderAccounts();if(page==='broadcasts')return renderBroadcasts();if(page==='profile')return renderProfile();return currentUser.role==='client'?renderClientHome():renderStaffHome()}
function renderClientHome(){return renderClientDashboard(data,currentUser)}
function metricRow(icon,label,type,value,target,unit){const pct=type==='steps'?Math.min(100,Math.round(value/8000*100)):type==='water'?Math.min(100,value/8*100):Math.min(100,value/7*100);const display=type==='steps'?Number(value).toLocaleString():value;return `<div style="padding:6px 0 10px"><div class="metric-top"><span class="metric-label">${icon} &nbsp;${label}</span><span style="font-size:10px;font-weight:700">${display} <span style="color:#94968d;font-weight:500">/ ${target}</span></span></div><div class="progress-line"><span style="width:${pct}%"></span></div></div>`}
function renderStaffHome(){const clientCount=data.users.filter(u=>u.role==='client').length,coachCount=data.users.filter(u=>u.role==='coach').length;return `<div class="page-heading"><div><div class="eyebrow">${roleName(currentUser.role)} workspace · ${todayLabel()}</div><h1>${currentUser.role==='admin'?'Studio overview':'Hello, '+esc(currentUser.name.split(' ')[0])}</h1><p>${currentUser.role==='admin'?'A snapshot of your BodyfyStudio community and content.':'Your tools to keep client journeys moving forward.'}</p></div><button class="btn btn-primary" data-action="new-broadcast">◉ &nbsp; Send a reminder</button></div><div class="grid grid-4">${metricCard('👥','Clients',clientCount,'Account directory')}${metricCard('🥗','Shared recipes',data.recipes.length,'Visible to all clients')}${metricCard('◉','Broadcasts',data.notifications.length,'Saved broadcasts')}${metricCard('✦','Coaches',coachCount,'Coach accounts')}</div><div class="grid grid-2" style="margin-top:18px"><section class="card"><div class="card-title-row"><h2 class="card-title">Quick actions</h2><span class="tag">${roleName(currentUser.role)}</span></div><div class="grid grid-2"><button class="btn btn-outline" data-action="new-broadcast">◉ &nbsp; Send a broadcast</button><button class="btn btn-outline" data-action="new-recipe">♧ &nbsp; Add a recipe</button>${currentUser.role==='admin'?'<button class="btn btn-outline" data-nav="accounts">♙ &nbsp; Manage accounts</button>':''}<button class="btn btn-outline" data-nav="recipes">▤ &nbsp; View recipe library</button></div><div class="notice-bar" style="margin-top:16px">Recipes, reminders, and account information are saved in your studio workspace.</div></section><section class="card"><div class="card-title-row"><h2 class="card-title">Recent broadcasts</h2><button class="link-button" data-nav="broadcasts">View all →</button></div>${data.notifications.length?data.notifications.slice(0,3).map(notificationRow).join(''):`<div class="empty-state"><div class="empty-icon">💬</div>No reminders yet. Send a quick note to your clients.</div>`}</section></div><div class="card" style="margin-top:18px"><div class="card-title-row"><h2 class="card-title">Recipe library</h2><button class="link-button" data-nav="recipes">Manage recipes →</button></div><div class="meal-list">${data.recipes.slice(0,4).map(r=>`<div class="meal-item"><div class="meal-emoji">${esc(r.emoji)}</div><div class="meal-meta"><strong>${esc(r.title)}</strong><span>${esc(r.category)} · ${r.time} min · shared with all clients</span></div><button class="link-button" data-recipe="${r.id}">View</button></div>`).join('')}</div></div>`}
function metricCard(icon,label,value,caption){return `<article class="card metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon}</span></div><div><div class="metric-value">${value}</div><div class="metric-change neutral">${caption}</div></div></article>`}
function renderPlan(){return renderSharedPlan(data)}
function renderRecipes(){const cats=['All','Saved','Breakfast','Lunch','Dinner','Snacks','Drinks'];let list=data.recipes.filter(r=>(activeFilter==='All'||(activeFilter==='Saved'&&(r.savedBy||[]).includes(currentUser.id))||r.category===activeFilter)&&(`${r.title} ${r.description} ${r.category}`).toLowerCase().includes(recipeQuery.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow">Coach-curated · Shared with everyone</div><h1>Good food, made simple.</h1><p>Browse healthy ideas from your BodyfyStudio coach. Find something nourishing for today.</p></div>${isCoach()?'<button class="btn btn-primary" data-action="new-recipe">＋ &nbsp; Add a recipe</button>':''}</div><div style="display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap"><div class="recipe-filter">${cats.map(c=>`<button class="filter-chip ${activeFilter===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div><label class="search-wrap"><span>⌕</span><input class="search-input" id="recipe-search" placeholder="Search recipes…" value="${esc(recipeQuery)}"></label></div><div class="recipe-grid">${list.length?list.map(recipeCard).join(''):`<div class="card empty-state" style="grid-column:1/-1"><div class="empty-icon">🍽️</div>No recipes match that search yet.</div>`}</div><div class="notice-bar" style="margin-top:18px">Nutrition estimates are illustrative. Follow your coach’s guidance for your individual needs.</div>`}
function recipeCard(r){const saved=(r.savedBy||[]).includes(currentUser.id);const idx=data.recipes.findIndex(x=>x.id===r.id);const art=r.art||['','art-1','art-2','art-3','art-4','art-5'][idx%6];return `<article class="card recipe-card"><div class="recipe-art ${art}">${esc(r.emoji)}<span style="position:absolute;left:12px;top:11px" class="tag">${esc(r.category)}</span></div><div class="recipe-body"><div class="recipe-meta"><span>◷ ${r.time} min</span><span>•</span><span>By ${esc(r.author||'BodyfyStudio coach')}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="recipe-foot"><span class="calorie">≈ ${r.calories} kcal · estimate</span><div style="display:flex;gap:6px"><button class="link-button" data-save-recipe="${r.id}" title="${saved?'Remove saved recipe':'Save recipe'}">${saved?'♥':'♡'}</button><button class="link-button" data-recipe="${r.id}">View →</button></div></div></div></article>`}
function renderNotifications(){const notices=[...data.notifications].sort((a,b)=>b.created-a.created);return `<div class="page-heading"><div><div class="eyebrow">Your updates</div><h1>Notifications</h1><p>Reminders and updates from your BodyfyStudio coach.</p></div><button class="btn btn-outline" data-action="mark-read">Mark all as read</button></div><section class="card"><div class="card-title-row"><h2 class="card-title">Recent updates</h2><span class="tag">${notices.length} total</span></div>${notices.length?`<div class="notification-list">${notices.map(notificationRow).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">🔔</div><strong>You’re all caught up.</strong><br>When your coach sends a reminder, it will show up here.</div>`}</section><div class="notice-bar" style="margin-top:15px">Inbox updates are saved in Supabase. Turn on device notifications in your profile to receive alerts while the app is closed.</div>`}
function notificationRow(n){const icon=n.kind==='zoom'?'🎥':n.kind==='water'?'💧':n.kind==='fruit'?'🍊':'✦';return `<article class="notification-item ${n.read?'':'unread'}"><div class="notification-icon ${n.kind==='zoom'?'orange':''}">${icon}</div><div class="notification-content"><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><time>${new Date(n.created).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})} · Coach broadcast</time>${n.kind==='zoom'&&n.link?`<div style="margin-top:10px"><a class="btn btn-primary btn-sm" href="${esc(n.link)}" target="_blank" rel="noopener noreferrer" data-notice-link="${n.id}">Join Zoom meeting ↗</a></div>`:''}</div>${n.read?'':'<span class="tag">New</span>'}</article>`}
function renderClients(){const clients=data.users.filter(u=>u.role==='client');return `<div class="page-heading"><div><div class="eyebrow">People you support</div><h1>Your clients</h1><p>Client accounts assigned to you by the studio admin.</p></div></div><section class="card"><div class="card-title-row"><h2 class="card-title">Assigned clients</h2><span class="tag">${clients.length} accounts</span></div>${accountTable(clients)}</section>`}
function renderAccounts(){if(managedAccountId)return '<div id="account-workspace"></div>';return `<div class="page-heading"><div><div class="eyebrow">Super admin controls</div><h1>Accounts & access</h1><p>Invite coaches and manage client and coach access.</p></div><button class="btn btn-primary" data-action="new-account">＋ &nbsp; Invite coach</button></div><div class="grid grid-4">${metricCard('♙','Clients',data.users.filter(u=>u.role==='client').length,'Client access')}${metricCard('✦','Coaches',data.users.filter(u=>u.role==='coach').length,'Coach access')}${metricCard('◆','Super admins',data.users.filter(u=>u.role==='admin').length,'Elevated access')}${metricCard('♧','Shared recipes',data.recipes.length,'Published to clients')}</div><section class="card" style="margin-top:18px"><div class="card-title-row"><h2 class="card-title">All accounts</h2><span class="tag">Role management</span></div>${accountTable(data.users)}</section><div class="notice-bar" style="margin-top:15px">Coach invitations are sent through a protected Supabase Edge Function. Super admin access is reserved for manual bootstrap.</div>`}
function accountTable(users){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Email</th><th>Role</th><th>Account</th>${currentUser.role==='admin'?'<th>Change role</th><th>Access</th>':''}</tr></thead><tbody>${users.map(u=>`<tr><td><div class="person-cell"><span class="avatar ${u.role==='coach'?'orange':''}">${esc(initials(u.name))}</span>${esc(u.name)}</div></td><td>${esc(u.email||'—')}</td><td>${roleName(u.role)}</td><td><span class="status-pill">Active</span></td>${currentUser.role==='admin'?`<td>${u.role==='admin'?'<span class="tag">Protected</span>':`<select class="search-input role-select" data-role-user="${u.id}" aria-label="Change role for ${esc(u.name)}" style="width:125px;padding:7px">${['client','coach'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleName(r)}</option>`).join('')}</select>`}</td><td>${u.role==='admin'?'—':`<button class="btn btn-outline btn-sm" data-open-account="${u.id}">Open account</button>`}</td>`:''}</tr>`).join('')||'<tr><td colspan="5">No accounts yet.</td></tr>'}</tbody></table></div>`}
function renderBroadcasts(){const history=[...data.notifications].sort((a,b)=>b.created-a.created);return `<div class="page-heading"><div><div class="eyebrow">Coach communication</div><h1>Broadcasts</h1><p>Share a helpful reminder with every client at once.</p></div><button class="btn btn-primary" data-action="new-broadcast">◉ &nbsp; Create broadcast</button></div><div class="grid grid-2"><section class="card"><div class="card-title-row"><h2 class="card-title">Quick reminders</h2><span class="tag">One tap</span></div><p style="font-size:11px;color:var(--muted);line-height:1.6;margin-top:-5px">Choose a gentle nudge and send it to your client community.</p><div class="grid grid-2" style="margin-top:16px"><button class="btn btn-outline" data-quick-broadcast="water">💧 &nbsp; Drink some water</button><button class="btn btn-outline" data-quick-broadcast="fruit">🍊 &nbsp; Have fresh fruit</button><button class="btn btn-outline" data-quick-broadcast="custom">✦ &nbsp; A little encouragement</button><button class="btn btn-outline" data-action="new-broadcast">🎥 &nbsp; Share a Zoom link</button></div><div class="notice-bar" style="margin-top:16px">Reminders are saved to every client inbox. Push alerts go to clients who enable them on a device.</div></section><section class="card"><div class="card-title-row"><h2 class="card-title">Preview on a client phone</h2><span class="tag">Example</span></div><div class="broadcast-preview"><small>BODYFYSTUDIO · NOW</small><p><strong>💧 A gentle water reminder</strong><br>Take a moment to drink a glass of water. Small habits add up!</p><small>Tap to open the BodyfyStudio app</small></div><div class="broadcast-preview"><small>BODYFYSTUDIO · NOW</small><p><strong>🎥 Your session starts now</strong><br>Your coach is ready. Tap below to join the Zoom session.</p><a class="link-button" href="https://zoom.us" target="_blank" rel="noopener noreferrer">Join Zoom meeting ↗</a></div></section></div><section class="card" style="margin-top:18px"><div class="card-title-row"><h2 class="card-title">Broadcast history</h2><span class="tag">${history.length} sent</span></div>${history.length?`<div class="notification-list">${history.map(notificationRow).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">📣</div>No broadcasts yet. Your sent reminders will appear here.</div>`}</section>`}
function renderProfile(){return `<div class="page-heading"><div><div class="eyebrow">Account settings</div><h1>Your profile</h1><p>Review your BodyfyStudio account.</p></div></div><section class="card" style="max-width:680px"><div style="display:flex;align-items:center;gap:14px;margin-bottom:22px"><div class="avatar" style="width:54px;height:54px;font-size:18px">${esc(initials(currentUser.name))}</div><div><h2 class="card-title" style="font-size:18px">${esc(currentUser.name)}</h2><div style="color:var(--muted);font-size:11px;margin-top:5px">${roleName(currentUser.role)} · ${esc(currentUser.email)}</div></div></div><div class="grid grid-2"><div><div class="metric-label">Name</div><strong style="font-size:12px;display:block;margin-top:6px">${esc(currentUser.name)}</strong></div><div><div class="metric-label">Access level</div><strong style="font-size:12px;display:block;margin-top:6px">${roleName(currentUser.role)}</strong></div><div><div class="metric-label">Email</div><strong style="font-size:12px;display:block;margin-top:6px">${esc(currentUser.email)}</strong></div><div><div class="metric-label">Storage</div><strong style="font-size:12px;display:block;margin-top:6px">Supabase</strong></div></div><div class="notice-bar" style="margin-top:20px">Your profile and sign-in are managed by Supabase.</div>${currentUser.role==='client'?`<div style="margin-top:18px;padding:16px;border:1px solid var(--line);border-radius:14px"><div class="card-title">Device notifications</div><p style="font-size:11px;color:var(--muted);line-height:1.6;margin:7px 0 12px">${pushSubscribed?'This device can receive coach reminders when BodyfyStudio is closed.':'Enable push alerts on this device for coach reminders, even when the app is closed.'} On iPhone, install the app on your Home Screen first.</p><button class="btn btn-outline" data-action="push-toggle">${pushSubscribed?'Turn off notifications':'Enable notifications'}</button></div>`:''}<button class="btn btn-outline" style="margin-top:17px" data-action="signout">Sign out</button></section>`}
function renderModal(){if(!modal)return '';if(modal.type==='recipe-view'){const r=data.recipes.find(x=>x.id===modal.id);if(!r){modal=null;return ''}return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span class="tag">${esc(r.category)}</span><h2 id="modal-title" style="margin-top:9px">${esc(r.title)}</h2><p>${r.time} min · approximately ${r.calories} kcal · Coach ${esc(r.author||'BodyfyStudio')}</p></div><button class="close-btn" data-action="close-modal" aria-label="Close">×</button></div><p style="font-size:12px;color:var(--muted);line-height:1.65">${esc(r.description)}</p><div class="grid grid-2"><div><h3 class="card-title">Ingredients</h3><ul style="padding-left:18px;color:#66685f;font-size:11px;line-height:1.9">${r.ingredients.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div><div><h3 class="card-title">Method</h3><ol style="padding-left:18px;color:#66685f;font-size:11px;line-height:1.9">${r.steps.map(i=>`<li>${esc(i)}</li>`).join('')}</ol></div></div><div class="notice-bar" style="margin:12px 0">Nutrition estimates are illustrative. Ask your coach whether this recipe suits your individual plan.</div><button class="btn btn-primary btn-block" data-save-recipe="${r.id}">${(r.savedBy||[]).includes(currentUser.id)?'♥ Saved to my favorites':'♡ Save this recipe'}</button></section></div>`}
if(modal.type==='recipe-new')return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Add a shared recipe</h2><p>Every client can browse published recipes.</p></div><button class="close-btn" data-action="close-modal" aria-label="Close">×</button></div><form id="recipe-form"><div class="field"><label>Recipe name</label><input name="title" required maxlength="70" placeholder="e.g. Simple veggie bowl"></div><div class="split-field"><div class="field"><label>Category</label><select name="category"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snacks</option><option>Drinks</option></select></div><div class="field"><label>Prep time (minutes)</label><input type="number" min="1" max="240" value="20" name="time" required></div></div><div class="split-field"><div class="field"><label>Calories (estimate)</label><input type="number" min="0" max="3000" value="300" name="calories"></div><div class="field"><label>Recipe emoji</label><input name="emoji" value="🥗" maxlength="4"></div></div><div class="field"><label>Short description</label><input name="description" required maxlength="140" placeholder="What makes this recipe easy and nourishing?"></div><div class="field"><label>Ingredients (one per line)</label><textarea name="ingredients" required placeholder="1 cup cooked lentils&#10;½ cucumber, chopped"></textarea></div><div class="field"><label>Method (one step per line)</label><textarea name="steps" required placeholder="Rinse and prepare the lentils.&#10;Mix with vegetables and season."></textarea></div><button class="btn btn-primary btn-block" type="submit">Publish to shared recipe library</button></form></section></div>`;
if(modal.type==='broadcast')return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Send a client broadcast</h2><p>One reminder for the whole community.</p></div><button class="close-btn" data-action="close-modal" aria-label="Close">×</button></div><form id="broadcast-form"><div class="field"><label>Reminder type</label><select name="kind" id="broadcast-kind"><option value="custom">Encouragement</option><option value="water">Drink water</option><option value="fruit">Fresh fruit</option><option value="zoom">Join a Zoom meeting</option></select></div><div class="field"><label>Title</label><input name="title" required maxlength="70" value="A gentle reminder from your coach"></div><div class="field"><label>Message</label><textarea name="message" required maxlength="220" placeholder="Write a short, supportive message for your clients."></textarea></div><div class="field" id="zoom-link-field" style="display:none"><label>Zoom meeting link</label><input name="link" type="url" placeholder="https://zoom.us/j/…"><span class="field-help">Use a trusted Zoom meeting URL. It opens when the client taps Join.</span></div><div class="notice-bar" style="margin-bottom:14px">Sends to every client inbox and push-enabled device.</div><button class="btn btn-primary btn-block" type="submit">Send broadcast →</button></form></section></div>`;
if(modal.type==='account')return `<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">Invite a coach</h2><p>They’ll receive an email to finish setting up their coach account.</p></div><button class="close-btn" data-action="close-modal" aria-label="Close">×</button></div><form id="account-form"><div class="field"><label>Coach name</label><input name="name" required maxlength="80" placeholder="Full name"></div><div class="field"><label>Email</label><input name="email" type="email" required maxlength="254" placeholder="coach@example.com"></div><div class="notice-bar" style="margin-bottom:14px">The invitation link grants coach access after the account is created. It cannot grant super admin access.</div><button class="btn btn-primary btn-block" type="submit">Send coach invitation</button></form></section></div>`;return ''}
function bindApp(){
if(currentUser?.role==='admin'){
  if(managedAccountId&&page==='accounts')accountWorkspace.mount(document.getElementById('account-workspace'));
  document.querySelectorAll('[data-open-account]').forEach(button=>button.onclick=()=>{
    managedAccountId=button.dataset.openAccount;
    render();
    accountWorkspace.open(managedAccountId,document.getElementById('account-workspace'));
  });
}
document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{page=b.dataset.nav;activeFilter='All';window.scrollTo({top:0,behavior:'smooth'});render()}));document.querySelectorAll('[data-action="signout"]').forEach(b=>b.onclick=signOut);document.querySelector('[data-action="push-toggle"]')?.addEventListener('click',togglePushNotifications);document.querySelectorAll('[data-action="new-recipe"]').forEach(b=>b.onclick=()=>openModal({type:'recipe-new'}));document.querySelectorAll('[data-action="new-broadcast"]').forEach(b=>b.onclick=()=>openModal({type:'broadcast'}));document.querySelectorAll('[data-action="new-account"]').forEach(b=>b.onclick=()=>openModal({type:'account'}));document.querySelectorAll('[data-action="close-modal"]').forEach(b=>b.onclick=()=>{modal=null;render()});document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',e=>{if(e.target===b){modal=null;render()}}));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>openModal({type:'recipe-view',id:b.dataset.recipe}));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;render()});const search=document.getElementById('recipe-search');search?.addEventListener('input',()=>{recipeQuery=search.value;const pos=search.selectionStart;render();const next=document.getElementById('recipe-search');next.focus();next.setSelectionRange(pos,pos)});personalController.bind();document.querySelectorAll('[data-action="new-broadcast"]').forEach(b=>b.onclick=()=>openModal({type:'broadcast'}));document.querySelectorAll('[data-quick-broadcast]').forEach(b=>b.onclick=()=>quickBroadcast(b.dataset.quickBroadcast));document.querySelectorAll('[data-role-user]').forEach(s=>s.onchange=()=>changeRole(s.dataset.roleUser,s.value));document.getElementById('recipe-form')?.addEventListener('submit',submitRecipe);document.getElementById('broadcast-form')?.addEventListener('submit',submitBroadcast);document.getElementById('account-form')?.addEventListener('submit',submitAccount);document.getElementById('broadcast-kind')?.addEventListener('change',e=>{const f=document.getElementById('zoom-link-field');f.style.display=e.target.value==='zoom'?'grid':'none';if(e.target.value==='water'){document.querySelector('[name="title"]').value='A gentle water reminder';document.querySelector('[name="message"]').value='Take a moment to drink a glass of water. Small habits add up!'}else if(e.target.value==='fruit'){document.querySelector('[name="title"]').value='A fresh fruit break';document.querySelector('[name="message"]').value='Pause for a fresh fruit today. A little nourishment can brighten your day.'}else if(e.target.value==='zoom'){document.querySelector('[name="title"]').value='Your coaching session is ready';document.querySelector('[name="message"]').value='Your coach is ready. Tap below to join the Zoom session.'}});}
function openModal(next){modal=next;render();if(next.type==='broadcast'){const select=document.getElementById('broadcast-kind');if(select)select.dispatchEvent(new Event('change'))}}
async function submitRecipe(e){e.preventDefault();if(!isCoach())return;const f=new FormData(e.currentTarget),recipe={author_id:currentUser.id,title:String(f.get('title')).trim(),category:String(f.get('category')),prep_minutes:Number(f.get('time')),calories_estimate:Number(f.get('calories')||0),emoji:String(f.get('emoji')||'🥗'),description:String(f.get('description')).trim(),ingredients:String(f.get('ingredients')).split('\n').map(x=>x.trim()).filter(Boolean),steps:String(f.get('steps')).split('\n').map(x=>x.trim()).filter(Boolean),published:true};const {error}=await supabase.from('recipes').insert(recipe);if(error){toast(`Could not publish recipe: ${error.message}`);return}modal=null;await refreshSharedData();page='recipes';render();toast('Recipe published to the shared library.')}
function validZoomUrl(input){try{const u=new URL(input);return u.protocol==='https:'&&(u.hostname==='zoom.us'||u.hostname.endsWith('.zoom.us'))?u.href:null}catch{return null}}
const pushJoinLink=new URLSearchParams(window.location.search).get('join');if(pushJoinLink){const safeJoinLink=validZoomUrl(pushJoinLink);if(safeJoinLink)window.location.replace(safeJoinLink)}
async function submitBroadcast(e){e.preventDefault();if(!isCoach())return;const f=new FormData(e.currentTarget),kind=String(f.get('kind'));let link=null;if(kind==='zoom'){link=validZoomUrl(String(f.get('link')||''));if(!link){toast('Enter a valid https://zoom.us meeting link.');return}}const {data:created,error}=await supabase.from('broadcasts').insert({author_id:currentUser.id,kind,title:String(f.get('title')).trim(),message:String(f.get('message')).trim(),action_url:link}).select('id').single();if(error){toast(`Could not send broadcast: ${error.message}`);return}const pushResult=await sendBroadcastPush(created.id);modal=null;await refreshSharedData();page='broadcasts';render();toast(pushResult?.error?`Broadcast saved to inboxes. Push failed: ${pushResult.error}`:pushResult?.message?`Broadcast saved to inboxes. ${pushResult.message}`:pushResult?`Broadcast sent. Push alerts sent to ${pushResult.sent||0} device(s).${pushResult.failed?` ${pushResult.failed} failed.`:''}`:'Broadcast saved to client inboxes, but push alerts could not be sent.')}
async function quickBroadcast(kind){const presets={water:{title:'A gentle water reminder',message:'Take a moment to drink a glass of water. Small habits add up!',kind:'water'},fruit:{title:'A fresh fruit break',message:'Pause for a fresh fruit today. A little nourishment can brighten your day.',kind:'fruit'},custom:{title:'A little encouragement',message:'You’re doing better than you think. Keep showing up for yourself, one small step at a time.',kind:'custom'}};const p=presets[kind];const {data:created,error}=await supabase.from('broadcasts').insert({author_id:currentUser.id,...p,action_url:null}).select('id').single();if(error){toast(`Could not send reminder: ${error.message}`);return}const pushResult=await sendBroadcastPush(created.id);await refreshSharedData();render();toast(pushResult?.error?`Reminder saved to inboxes. Push failed: ${pushResult.error}`:pushResult?.message?`Reminder saved to inboxes. ${pushResult.message}`:pushResult?`Reminder sent. Push alerts sent to ${pushResult.sent||0} device(s).${pushResult.failed?` ${pushResult.failed} failed.`:''}`:'Reminder saved to client inboxes, but push alerts could not be sent.')}
async function submitAccount(e){e.preventDefault();if(currentUser?.role!=='admin'){toast('Only a super admin can invite a coach.');return}const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),fields=new FormData(form);button.disabled=true;const {data:result,error}=await supabase.functions.invoke('admin-invite-coach',{body:{name:String(fields.get('name')).trim(),email:String(fields.get('email')).trim().toLowerCase()}});button.disabled=false;if(error){let detail=error.message;try{const response=error.context?.clone?.();if(response){const body=await response.json();detail=body.error||detail}}catch{}toast(`Could not invite coach: ${detail}`);return}modal=null;await refreshSharedData();await loadAdminDirectory();render();toast(`Coach invitation sent to ${result.email}.`)}
async function changeRole(id,role){if(currentUser?.role!=='admin'||id===currentUser.id||!['client','coach'].includes(role)){render();toast('That role change is not allowed.');return}const {error}=await supabase.rpc('admin_set_user_role',{target_user:id,new_role:role});if(error){toast(`Could not update role: ${error.message}`);return}await refreshSharedData();await loadAdminDirectory();render();toast('Account role updated.')}
let deferredInstall=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;document.querySelector('.top-actions')?.insertAdjacentHTML('afterbegin','<button class="btn btn-primary btn-sm" data-install>Install app</button>');document.querySelector('[data-install]')?.addEventListener('click',installApp)});
async function installApp(){if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;document.querySelector('[data-install]')?.remove()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}});
app.innerHTML='<main class="auth-screen"><section class="auth-panel"><div class="auth-box">Connecting securely to BodyfyStudio…</div></section></main>';
async function refreshOnResume(){if(!currentUser||document.visibilityState!=='visible'||resumeCheckPending||personalController.busy()||Date.now()-resumeCheckAt<5000)return;resumeCheckPending=true;resumeCheckAt=Date.now();try{const response=await fetch(`/version.json?check=${Date.now()}`,{cache:'no-store'});if(response.ok){const {buildId}=await response.json();if(buildId&&buildId!==APP_BUILD_ID){try{const registration=await navigator.serviceWorker?.getRegistration();await registration?.update()}catch{}window.location.reload();return}}await refreshSharedData();if(currentUser?.role==='admin')await loadAdminDirectory();if(currentUser?.role==='client')await refreshPushStatus();if(!isEditing())render()}catch(error){console.warn('App resume refresh failed:',error)}finally{resumeCheckPending=false}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshOnResume()});
window.addEventListener('pageshow',()=>{if(document.visibilityState==='visible')refreshOnResume()});
window.addEventListener('online',refreshOnResume);
setInterval(async()=>{if(currentUser?.role==='client'&&document.visibilityState==='visible'&&data.personal?.day!==localDay()&&!personalController.busy()){await refreshSharedData();if(!isEditing())render()}},60000);
supabase.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){personalController.reset();currentUser=null;data=emptyData();modal=null;managedAccountId=null;accountWorkspace.close();clearTimeout(liveRefreshTimer);renderLogin()}else if(event==='PASSWORD_RECOVERY'){passwordSetupFlow=true;renderPasswordSetup()}else if(event==='SIGNED_IN'&&session&&passwordSetupFlow){renderPasswordSetup()}else if(event==='SIGNED_IN'&&session&&currentUser?.id!==session.user.id){setTimeout(()=>acceptSession(session),0)}});
supabase.auth.getSession().then(({data:sessionData,error})=>{if(error){toast(`Could not restore your session: ${error.message}`);renderLogin();return}if(sessionData.session&&passwordSetupFlow)renderPasswordSetup();else if(sessionData.session)acceptSession(sessionData.session);else renderLogin()});
document.addEventListener('click',async event=>{const link=event.target.closest('[data-notice-link]');if(link&&currentUser?.role==='client'){const {error}=await supabase.from('broadcast_recipients').update({read_at:new Date().toISOString()}).eq('broadcast_id',link.dataset.noticeLink).eq('client_id',currentUser.id);if(error)toast(`Could not update inbox: ${error.message}`);else{const notice=data.notifications.find(x=>x.id===link.dataset.noticeLink);if(notice)notice.read=true}return}const markAll=event.target.closest('[data-action="mark-read"]');if(markAll&&currentUser?.role==='client'){const {error}=await supabase.from('broadcast_recipients').update({read_at:new Date().toISOString()}).eq('client_id',currentUser.id).is('read_at',null);if(error)toast(`Could not update inbox: ${error.message}`);else{await refreshSharedData();render();toast('All notifications marked as read.')}}});
